var a=241;var i=[{id:`cooking-241-01`,theoryId:241,type:`single_choice`,difficulty:`beginner`,safetyCritical:!1,question:{en:`Why finish cooked pasta in a pan of sauce with a little starchy pasta water?`,ua:`Навіщо завершувати приготування пасти в сковороді із соусом і невеликою кількістю крохмалистої води?`},explanation:{en:`Released starch and agitation can help bind water and fat in a coating sauce.`,ua:`Вивільнений крохмаль і перемішування допомагають поєднати воду та жир у соусі, який огортає пасту.`},options:[{id:`a`,text:{en:`To turn pasta into risotto`,ua:`Щоб перетворити пасту на ризото`}},{id:`b`,text:{en:`To help the sauce cling and emulsify`,ua:`Щоб соус краще огортав пасту й емульгувався`}},{id:`c`,text:{en:`To sterilize the pasta for long-term storage`,ua:`Щоб стерилізувати пасту для тривалого зберігання`}}],answer:{optionIds:[`b`]}},{id:`cooking-241-02`,theoryId:241,type:`true_false`,difficulty:`beginner`,safetyCritical:!1,question:{en:`Italian cooking has a single universal set of ingredients and techniques in every region.`,ua:`У всіх регіонах Італії існує єдиний набір інгредієнтів і способів приготування.`},explanation:{en:`Northern and southern Italian traditions differ widely in grains, fats, pasta and seasonings.`,ua:`Північні та південні італійські традиції суттєво різняться крупами, жирами, пастою та приправами.`},answer:{value:!1}},{id:`cooking-241-03`,theoryId:241,type:`matching`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Match the ingredient or technique with its role in an Italian dish.`,ua:`Поєднайте інгредієнт або техніку з її роллю в італійській страві.`},explanation:{en:`Ingredient function depends on the dish and its region.`,ua:`Функція інгредієнта залежить від страви та регіону.`},leftItems:[{id:`l1`,text:{en:`Risotto stirring`,ua:`Перемішування ризото`}},{id:`l2`,text:{en:`Pasta water`,ua:`Вода з-під пасти`}},{id:`l3`,text:{en:`Olive oil`,ua:`Оливкова олія`}}],rightItems:[{id:`r2`,text:{en:`Supplies dissolved starch`,ua:`Містить розчинений крохмаль`}},{id:`r3`,text:{en:`Adds fat and aromatic character`,ua:`Додає жир і ароматичний характер`}},{id:`r1`,text:{en:`Helps release rice starch`,ua:`Сприяє вивільненню рисового крохмалю`}}],answer:{pairs:[{leftId:`l1`,rightId:`r1`},{leftId:`l2`,rightId:`r2`},{leftId:`l3`,rightId:`r3`}]}},{id:`cooking-241-04`,theoryId:241,type:`decision_scenario`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`A tomato sauce is too thin to coat pasta. What should the cook try first?`,ua:`Томатний соус надто рідкий і не огортає пасту. Що спробувати насамперед?`},explanation:{en:`Reduction changes concentration; final tossing promotes coating.`,ua:`Уварювання збільшує концентрацію, а перемішування пасти із соусом покращує покриття.`},options:[{id:`a`,text:{en:`Reduce it appropriately, then finish the pasta in the sauce`,ua:`Обережно уварити, а потім завершити пасту в соусі`}},{id:`b`,text:{en:`Rinse the pasta in cold water before serving`,ua:`Промити пасту холодною водою перед подачею`}},{id:`c`,text:{en:`Add a large amount of sugar`,ua:`Додати багато цукру`}}],answer:{optionIds:[`a`]}},{id:`cooking-241-05`,theoryId:241,type:`multiple_choice`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Which statements are sound for studying Italian regional cooking?`,ua:`Які твердження правильні під час вивчення регіональних італійських кухонь?`},explanation:{en:`Regional practice and ingredient behavior matter more than stereotypes.`,ua:`Регіональні практики та властивості інгредієнтів важливіші за стереотипи.`},options:[{id:`a`,text:{en:`Use appropriate seasonal ingredients when possible`,ua:`За можливості використовувати відповідні сезонні інгредієнти`}},{id:`b`,text:{en:`Research the regional context of a dish`,ua:`Досліджувати регіональний контекст страви`}},{id:`c`,text:{en:`Assume every region uses the same primary fat`,ua:`Вважати, що всі регіони використовують один основний жир`}},{id:`d`,text:{en:`Distinguish risotto rice from typical dried pasta methods`,ua:`Відрізняти метод ризото від типового приготування сухої пасти`}}],answer:{optionIds:[`b`,`a`,`d`]}},{id:`cooking-241-06`,theoryId:241,type:`sequence`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`For a simple pasta with tomato sauce, order the final steps.`,ua:`Для простої пасти з томатним соусом упорядкуйте завершальні кроки.`},explanation:{en:`The sauce finishes cooking the pasta and forms a coating.`,ua:`Соус завершує приготування пасти й утворює покриття.`},steps:[{id:`s4`,text:{en:`Taste and serve immediately`,ua:`Скуштувати та відразу подати`}},{id:`s1`,text:{en:`Cook pasta until just short of desired texture`,ua:`Зварити пасту майже до потрібної текстури`}},{id:`s2`,text:{en:`Reserve a little starchy pasta water`,ua:`Відкласти трохи крохмалистої води`}},{id:`s3`,text:{en:`Toss pasta with warm sauce, adding water as needed`,ua:`Перемішати пасту з теплим соусом, додаючи воду за потреби`}}],answer:{order:[`s1`,`s2`,`s3`,`s4`]}}];var n={theoryId:241,exercises:i};export{n as default,i as exercises,a as theoryId};